/// Loads the private key for the matching sign bench.
///
/// `#[inline(never)]` matters: the encoded key bytes and the temporaries of decoding then live in
/// this frame, which is popped before the measured operation runs, so the bench's peak is
/// max(key load, sign) rather than their sum. Inlining this into the bench would leave them
/// on the stack underneath it and inflate the measurement by several kB.
