fn bench_mldsa87_sign() {
    use bouncycastle::mldsa::{MLDSA87, MLDSATrait};

    eprintln!("MLDSA87/Sign");

    /* One-time setup of the KAT -- commented out so that keygen is not captured in the bench */
    // let seed = KeyMaterial256::from_bytes_as_type(
    //     &[0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x1f],
    //     KeyType::Seed,
    // ).unwrap();
    // let (_pk, sk) = MLDSA87::keygen_from_seed(&seed).unwrap();
    // use bouncycastle_hex as hex;
    // eprintln!("sk:\n{}", &hex::encode(sk.encode()));

    let msg = b"The quick brown fox jumped over the lazy dog";

    // let (_pk, sk) = MLDSA87::keygen_from_seed(&seed).unwrap();
    let sk = load_mldsa87_sk();

    measure(|| {
        let mu = MLDSA87::compute_mu_from_sk(&sk, msg, None).unwrap();
        let sig = MLDSA87::sign_mu_deterministic(&sk, None, &mu, [0u8; 32]).unwrap();
        print!("{:x?}", sig);
    });
}

/// Same as bench_mldsa87_sign(), but with a pre-expanded private key.
///
/// The matrix A_hat is expanded up-front and handed to the signature, which is what makes repeated
/// signatures with the same key cheaper -- at the cost of the memory A_hat occupies for as long
/// as it is held.
///
/// Only the signature is measured, not the expansion: building an MLDSA87PrivateKeyExpanded
/// inside this function would put its own peak (which exceeds a whole signature) into the
/// measurement, the way a keygen would. This calls the same entry point as bench_mldsa87_sign(),
/// differing only in passing Some(&a_hat) instead of None, so the two are comparable.
///
fn bench_mldsa87_sign_expanded_sk() {
    use bouncycastle::mldsa::{MLDSA87, MLDSAPrivateKeyTrait, MLDSATrait};

    eprintln!("MLDSA87/Sign_with_expanded_key");

    /* One-time setup of the KAT -- commented out so that keygen is not captured in the bench */
    // let seed = KeyMaterial256::from_bytes_as_type(
    //     &[0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x1f],
    //     KeyType::Seed,
    // ).unwrap();
    // let (_pk, sk) = MLDSA87::keygen_from_seed(&seed).unwrap();
    // use bouncycastle_hex as hex;
    // eprintln!("sk:\n{}", &hex::encode(sk.encode()));

    let msg = b"The quick brown fox jumped over the lazy dog";

    // let (_pk, sk) = MLDSA87::keygen_from_seed(&seed).unwrap();
    let sk = load_mldsa87_sk();

    measure(|| {
        let a_hat = sk.A_hat();
        let mu = MLDSA87::compute_mu_from_sk(&sk, msg, None).unwrap();
        let sig = MLDSA87::sign_mu_deterministic(&sk, Some(&a_hat), &mu, [0u8; 32]).unwrap();
        print!("{:x?}", sig);
    });
}

/// Loads the private key for the matching sign bench. See [`load_mldsa44_sk`] for why this is
/// `#[inline(never)]`.
#[inline(never)]
fn load_mldsa87_lowmemory_sk() -> bouncycastle::mldsa_lowmemory::MLDSA87PrivateKey {
    use bouncycastle::mldsa_lowmemory::MLDSA87PrivateKey;

    MLDSA87PrivateKey::from_bytes(&[
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E,
        0x0F, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D,
        0x1E, 0x1F,
    ])
    .unwrap()
}

fn bench_mldsa87_lowmemory_sign() {
    use bouncycastle::mldsa_lowmemory::{MLDSA87, MLDSA87_SK_LEN, MLDSATrait};

    eprintln!("MLDSA87_lowmemory/Sign");

    /* One-time setup of the KAT -- commented out so that keygen is not captured in the bench */
    // let seed = KeyMaterial256::from_bytes_as_type(
    //     &[0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x1f],
    //     KeyType::Seed,
    // ).unwrap();
    // let (_pk, sk) = MLDSA65::keygen_from_seed(&seed).unwrap();
    // use bouncycastle_hex as hex;
    // eprintln!("sk:\n{}", &hex::encode(sk.encode()));

    let sk = load_mldsa87_lowmemory_sk();

    let msg = b"The quick brown fox jumped over the lazy dog";

    measure(|| {
        let mu = MLDSA87::compute_mu_from_sk(&sk, msg, None).unwrap();
        let sig = MLDSA87::sign_mu_deterministic(&sk, &mu, [0u8; 32]).unwrap();
        print!("{:x?}", sig);
    });
}

