///
/// The matrix A_hat is expanded up-front and held inside the MLDSA44PublicKeyExpanded, which is
/// what makes repeated verifications against the same key cheaper -- at the cost of the memory the
/// expanded key occupies for as long as it is held. Both the expansion and the verification are
/// inside the measurement.
